    }

    It 'records a keep-latest reason on deleted artifacts' {
        $plan = Get-ArtifactDeletionPlan -Artifacts $script:Artifacts -KeepLatestN 1 -Now $script:Now
        $plan.Delete[0].Reason | Should -Match 'keep'
